      "Your verification code: {code}": "Tu código de verificación: {code}",
      "Enter this code in the browser where you started account setup. It expires in ten minutes. This code verifies your email; it does not sign you in or replace your passkey, password or recovery file.": "Introduce este código en el navegador donde empezaste a configurar la cuenta. Caduca en diez minutos. El código verifica tu correo; no inicia sesión ni sustituye tu llave de acceso, contraseña o archivo de recuperación.",
      "If you did not request this code, ignore this message.": "Si no solicitaste este código, ignora este mensaje.",
      "Choose how we can reach you.": "Elige cómo podemos contactarte.",
      "Enable notifications on this device or verify an email before your account opens.": "Activa las notificaciones en este dispositivo o verifica un correo antes de abrir tu cuenta.",
      "For unpaid accounts, we might check in periodically to ask if you’re still using the account.": "En las cuentas gratuitas, podríamos contactarte periódicamente para preguntar si sigues usando la cuenta.",
      "After multiple unanswered notices and a grace period, an unpaid account may be suspended, then deleted. Deletion removes data hosted here; data in connected external providers is not deleted.": "Después de varios avisos sin respuesta y un período de gracia, una cuenta gratuita puede suspenderse y luego eliminarse. Se eliminan los datos alojados aquí; los datos de proveedores externos conectados no se eliminan.",
      "Accounts that have ever had a paid subscription are protected from automatic inactivity deletion.": "Las cuentas que hayan tenido una suscripción de pago están protegidas frente a la eliminación automática por inactividad.",
