      "Canonical handle": "Nombre de usuario canónico",
      "Custom handle": "Nombre de usuario personalizado",
      "Your recovery file protects your UUID and keys. Name certificates are separate public files.": "Tu archivo de recuperación protege tu UUID y tus claves. Los certificados de nombre son archivos públicos separados.",
      "Download canonical name certificate": "Descargar certificado del nombre canónico",
      "Download custom name certificate": "Descargar certificado del nombre personalizado",
      "Your permanent custom handle": "Tu nombre de usuario personalizado permanente",
      "If you have ever had a verified paid subscription, you can claim one custom handle—even after cancellation.": "Si alguna vez has tenido una suscripción de pago verificada, puedes obtener un nombre personalizado, incluso después de cancelarla.",
      "This choice is permanent. Your custom handle cannot be changed, transferred or reassigned, even after cancellation or account deletion.": "Esta elección es permanente. Tu nombre personalizado no puede cambiarse, transferirse ni reasignarse, incluso después de cancelar o eliminar la cuenta.",
      "Your permanent custom handle is already assigned.": "Tu nombre personalizado permanente ya está asignado.",
      "Use 3–32 lowercase letters, digits, underscores or hyphens, starting with a letter or digit.": "Usa entre 3 y 32 letras minúsculas, dígitos, guiones bajos o guiones, empezando por una letra o un dígito.",
      "I understand this is my one permanent custom handle.": "Entiendo que este es mi único nombre personalizado permanente.",
      "Claiming requires a recent sign-in. Your subscription history is checked by the service.": "Para obtenerlo, debes haber iniciado sesión recientemente. El servicio verifica tu historial de suscripciones.",
      "Claim permanent handle": "Obtener nombre permanente",
      "This identity already has its permanent custom handle.": "Esta identidad ya tiene su nombre personalizado permanente.",
      "Confirm that this is your one permanent custom handle.": "Confirma que este es tu único nombre personalizado permanente.",
      "Your permanent custom handle is ready. Your identity and recovery file stay the same.": "Tu nombre personalizado permanente está listo. Tu identidad y tu archivo de recuperación siguen siendo los mismos.",
      "Choose one of your assigned handles.": "Elige uno de tus nombres de usuario asignados.",
      "The service returned an invalid name certificate.": "El servicio devolvió un certificado de nombre no válido.",
      "Name certificate downloaded. It is public proof of your name assignment, separate from your private recovery file.": "Certificado de nombre descargado. Es una prueba pública de la asignación de tu nombre, separada de tu archivo de recuperación privado.",
      "A verified paid subscription is required to claim a custom handle.": "Se requiere un historial de suscripción de pago verificada para obtener un nombre personalizado.",
      "This identity already has a permanent custom handle.": "Esta identidad ya tiene un nombre personalizado permanente.",
      "This handle is permanently assigned or you already claimed another handle.": "Este nombre ya está asignado permanentemente o ya obtuviste otro nombre.",
      "Custom handles are unavailable for this identity.": "Los nombres personalizados no están disponibles para esta identidad.",
      "e.g. 7river": "p. ej. 7rio",
      "Choose a secure way to sign in to your free account.": "Elige una forma segura de iniciar sesión en tu cuenta gratuita.",
      "Your free account gets a unique handle starting with n. We show your assigned handle during setup. Handles are never reassigned.": "Tu cuenta gratuita recibe un nombre de usuario único que empieza por n. Lo verás durante la configuración. Los nombres de usuario nunca se reasignan.",
