      "Shortcuts run only when their context matches. Text editing and reserved browser keys stay available.": "Los atajos funcionan solo cuando coincide su contexto. La edición de texto y las teclas reservadas del navegador siguen disponibles.",
      "This is not end-to-end encrypted storage. Private API responses are never cached by the service worker. No third-party analytics are loaded by this interface.": "Este almacenamiento no tiene cifrado de extremo a extremo. El trabajador de servicio nunca almacena las respuestas privadas de la API. La interfaz no carga herramientas de análisis de terceros.",
      "This service processes account credentials, messages, resource settings, and access records to provide your account. Connector credentials are held by the service; the operator may access plaintext data.": "Este servicio procesa credenciales, mensajes, ajustes de recursos y registros de acceso para proporcionar tu cuenta. El servicio conserva las credenciales de los conectores; el operador puede acceder a los datos sin cifrar.",
      "Type a command": "Escribe un comando",
      "Use mod for Command on Apple devices or Control elsewhere. Separate chord strokes with a space. Invalid or conflicting entries are shown before they can run.": "Usa mod para Command en dispositivos Apple o Control en los demás. Separa las teclas de una secuencia con espacios. Se muestran los errores y conflictos antes de ejecutar.",
      "Use your account lawfully and respect others. Keep your credentials and recovery file safe. You are responsible for the contact links and resource access you authorize.": "Usa tu cuenta legalmente y respeta a los demás. Protege tus credenciales y tu archivo de recuperación. Eres responsable de los enlaces y accesos a recursos que autorizas.",
      "User override": "Cambio del usuario",
      "Waiting for next key…": "Esperando la siguiente tecla…",
      "WebDAV": "WebDAV",
      "What would you like to do?": "¿Qué te gustaría hacer?",
      "When clause": "Condición de contexto",
      "When clauses support view, dialogOpen, textInputFocus, selectionCount, authenticated, and offline. Use !, &&, ||, parentheses, and quoted equality values. User overrides win when contexts overlap.": "Las condiciones admiten view, dialogOpen, textInputFocus, selectionCount, authenticated y offline. Usa !, &&, ||, paréntesis y valores entre comillas. Los cambios del usuario tienen prioridad cuando los contextos coinciden.",
      "You are approving access to ": "Estás aprobando el acceso a ",
      "e.g. Close friends": "p. ej., Amigos cercanos",
      "e.g. Friends, projects, receipts": "p. ej., Amigos, proyectos, recibos",
      "e.g. Personal phone": "p. ej., Teléfono personal",
      "e.g. mod+k mod+i": "p. ej., mod+k mod+i",
      "e.g. river": "p. ej., river",
      "Publications per page": "Publicaciones por página",
      "PROTECT YOUR RECOVERY FILE": "PROTEGE TU ARCHIVO DE RECUPERACIÓN",
      "Private passphrase": "Frase secreta privada",
      "Text answer": "Respuesta de texto",
      "Date of birth / date": "Fecha de nacimiento / fecha",
      "Phone number": "Número de teléfono",
      "Social Security number": "Número de Seguridad Social",
      "National ID": "Identificación nacional",
      "PIN": "PIN",
      "Choose the questions you want to answer when you unlock this file. Every selected answer is required.": "Elige las preguntas que responderás al desbloquear este archivo. Todas las respuestas seleccionadas son obligatorias.",
      "Questions and hints stay readable.": "Las preguntas y las pistas se podrán leer.",
      "Answers encrypt your recovery secret on this device. Birthdays, phone numbers, IDs, and short PINs may be guessed offline. Include a private passphrase that someone else cannot guess.": "Las respuestas cifran tu secreto de recuperación en este dispositivo. Las fechas de nacimiento, los teléfonos, los identificadores y los PIN cortos se pueden adivinar sin conexión. Incluye una frase secreta privada que otra persona no pueda adivinar.",
      "Move up": "Subir",
      "Move down": "Bajar",
      "Answer type": "Tipo de respuesta",
      "Question": "Pregunta",
      "Public hint (optional)": "Pista pública (opcional)",
      "e.g. What is my private recovery passphrase?": "p. ej., ¿Cuál es mi frase secreta privada de recuperación?",
      "Do not put the answer in the hint.": "No escribas la respuesta en la pista.",
      "Choose a calendar date; the file records YYYY-MM-DD.": "Elige una fecha del calendario; el archivo la guarda como AAAA-MM-DD.",
      "Include the country calling code. Keep national leading zeros. Use this same original number when unlocking later.": "Incluye el prefijo internacional. Conserva los ceros iniciales del número nacional. Usa este mismo número original al desbloquear el archivo más adelante.",
      "Leading zeros are part of your answer.": "Los ceros iniciales forman parte de tu respuesta.",
      "Text answers ignore letter case and repeated whitespace. Accents and punctuation still matter.": "Las respuestas de texto ignoran las mayúsculas y los espacios repetidos. Los acentos y la puntuación siguen siendo importantes.",
      "A private passphrase preserves exact letter case and spaces.": "La frase secreta privada conserva exactamente las mayúsculas y los espacios.",
      "Add a question": "Añadir una pregunta",
      "Remember every answer. We cannot decrypt the file or reset these answers. Changing a phone number or other answer later does not update a file already saved.": "Recuerda todas las respuestas. No podemos descifrar el archivo ni restablecerlas. Cambiar un teléfono u otra respuesta más adelante no actualiza un archivo que ya hayas guardado.",
      "Encrypt recovery file": "Cifrar el archivo de recuperación",
      "Test your saved recovery file.": "Prueba tu archivo de recuperación guardado.",
      "CHECK YOUR WAY BACK IN": "COMPRUEBA CÓMO RECUPERAR EL ACCESO",
      "Enter every answer again. The questions and hints below come from the encrypted file.": "Introduce todas las respuestas otra vez. Las preguntas y las pistas siguientes proceden del archivo cifrado.",
      "Questions and hints are readable and are untrusted file content. Personal information may be guessed offline; protect the file and remember every original answer.": "Las preguntas y las pistas se pueden leer y son contenido no verificado del archivo. La información personal se puede adivinar sin conexión; protege el archivo y recuerda todas las respuestas originales.",
      "Test unlock": "Probar el desbloqueo",
      "Unlock recovery file": "Desbloquear el archivo de recuperación",
      "The file could not be decrypted. Check every answer and the recovery file.": "No se pudo descifrar el archivo. Revisa todas las respuestas y el archivo de recuperación.",
      "We could not prepare the recovery key on this device.": "No se pudo preparar la clave de recuperación en este dispositivo.",
      "Unsupported or malformed encrypted recovery file.": "El archivo de recuperación cifrado es incompatible o no tiene un formato válido.",
      "Recovery file is too large.": "El archivo de recuperación es demasiado grande.",
      "Recovery file must contain valid JSON.": "El archivo de recuperación debe contener JSON válido.",
      "Answer every selected recovery question.": "Responde todas las preguntas de recuperación seleccionadas.",
      "Use a date in YYYY-MM-DD format.": "Usa una fecha en formato AAAA-MM-DD.",
