      "Select your encrypted recovery file. Questions and hints are readable; all answers stay on this device.": "Selecciona tu archivo de recuperación cifrado. Las preguntas y las pistas se pueden leer; todas las respuestas permanecen en este dispositivo.",
      "Encrypted recovery file": "Archivo de recuperación cifrado",
