      "ACCOUNT SETUP": "CONFIGURACIÓN DE LA CUENTA",
      "Start with your account.": "Empieza por tu cuenta.",
      "This recovery screen needs an account setup in the same browser tab.": "Esta pantalla de recuperación necesita una configuración de cuenta en la misma pestaña del navegador.",
      "Return to sign in": "Volver al inicio de sesión",
