      "RECOVERY FILE TESTED": "ARCHIVO DE RECUPERACIÓN COMPROBADO",
      "Your way back in is ready.": "Ya puedes recuperar el acceso.",
      "Your answers unlocked the encrypted file on this device. Save this file somewhere private, separate from this device.": "Tus respuestas desbloquearon el archivo cifrado en este dispositivo. Guarda el archivo en un lugar privado, separado de este dispositivo.",
      "ENCRYPTED ON YOUR DEVICE": "CIFRADO EN TU DISPOSITIVO",
      "Save your encrypted recovery file.": "Guarda tu archivo de recuperación cifrado.",
      "Every selected answer is required to unlock it. We cannot replace a lost file or reset its answers.": "Necesitas todas las respuestas seleccionadas para desbloquearlo. No podemos reemplazar un archivo perdido ni restablecer sus respuestas.",
