      "Download your encrypted recovery file before testing it.": "Descarga tu archivo de recuperación cifrado antes de comprobarlo.",
      "This recovery file does not match the pending account.": "Este archivo de recuperación no corresponde a la cuenta pendiente.",
      "Download your encrypted recovery file, test its answers, and confirm it is saved before continuing.": "Descarga tu archivo de recuperación cifrado, comprueba las respuestas y confirma que lo has guardado antes de continuar.",
