      "Storage": "Almacenamiento",
      "Storage writes are paused while retained uploads are cleaned up.": "Las escrituras de almacenamiento están pausadas mientras se limpian las cargas retenidas.",
      "{daily} activity units per 24 hours · {hourly} per hour": "{daily} unidades de actividad por 24 horas · {hourly} por hora",
      "Paid": "De pago",
      "Ultra": "Ultra",
      "Room for your largest projects.": "Espacio para tus proyectos más grandes.",
      "I authorize this plan change and the immediate prorated adjustment, including any charge to my saved payment method or credit.": "Autorizo este cambio de plan y el ajuste prorrateado inmediato, incluido cualquier cargo a mi método de pago guardado o crédito.",
      "Polar will issue an invoice immediately and calculate the prorated adjustment. It may charge your saved payment method or create a credit. The exact adjustment is not previewed here.": "Polar emitirá una factura inmediatamente y calculará el ajuste prorrateado. Puede cobrar a tu método de pago guardado o generar un crédito. Aquí no se muestra una vista previa del ajuste exacto.",
      "Create a {brand} account": "Crear una cuenta en {brand}",
      "Account storage": "Almacenamiento de la cuenta",
      "Recheck the previous plan change before starting another.": "Comprueba el cambio de plan anterior antes de iniciar otro.",
      "Your subscription currency could not be verified. Refresh billing to continue.": "No se pudo verificar la moneda de tu suscripción. Actualiza la facturación para continuar.",
      "Review and authorize the plan change before continuing.": "Revisa y autoriza el cambio de plan antes de continuar.",
      "The plan changed after your review. Refresh prices and review it again.": "El plan cambió después de tu revisión. Actualiza los precios y revísalo de nuevo.",
