      "I confirm the lower plan and its recurring price beginning at the next renewal.": "Confirmo el plan inferior y su precio recurrente a partir de la próxima renovación.",
      "Review your plan change": "Revisa tu cambio de plan",
      "This change keeps your subscription currency: {currency}.": "Este cambio mantiene la moneda de tu suscripción: {currency}.",
      "Polar will issue the upgrade invoice immediately and calculate any prorated charge. The exact prorated amount is not previewed here.": "Polar emitirá la factura de la mejora inmediatamente y calculará cualquier cargo prorrateado. Aquí no se muestra una vista previa del importe prorrateado exacto.",
      "The lower plan starts at the next renewal. Your current capacity remains available until then.": "El plan inferior comienza en la próxima renovación. Tu capacidad actual seguirá disponible hasta entonces.",
      "Your current content exceeds the lower capacity. New uploads will pause at renewal until you reduce usage; reading and deletion remain available.": "Tu contenido actual supera la capacidad inferior. Las cargas se pausarán al renovar hasta que reduzcas el uso; podrás seguir leyendo y eliminando.",
      "Your review is out of date. Choose the plan again to review its current terms.": "Tu revisión ya no está actualizada. Elige de nuevo el plan para revisar sus condiciones actuales.",
