      "This contact link is incomplete. Open the original link again.": "Este enlace de contacto está incompleto. Abre de nuevo el enlace original.",
      "Your identity response could not be created. Try again.": "No se pudo crear tu respuesta de identidad. Inténtalo de nuevo.",
      "Sign in and confirm eligibility before sending.": "Inicia sesión y confirma el acceso antes de enviar.",
      "This link does not accept written messages.": "Este enlace no acepta mensajes escritos.",
      "Write a message before sending.": "Escribe un mensaje antes de enviar.",
