      "The new contact link could not be loaded.": "No se pudo cargar el nuevo enlace de contacto.",
      "Contact link created.": "Enlace de contacto creado.",
      "These tags changed in another window. Review the current settings and save again.": "Estas etiquetas cambiaron en otra ventana. Revisa la configuración actual y guarda de nuevo.",
      "Tags updated. Future messages use them; the link itself is unchanged.": "Etiquetas actualizadas. Los mensajes futuros las usarán; el enlace no cambia.",
      "Challenge rotated. The previous link no longer works.": "Desafío renovado. El enlace anterior ya no funciona.",
      "Default rule restored.": "Regla predeterminada restaurada.",
      "Use a label of up to 64 characters.": "Usa un nombre de hasta 64 caracteres.",
      "Tag label saved. Messages keep their tags.": "Nombre de etiqueta guardado. Los mensajes conservan sus etiquetas.",
      "This link currently accepts messages from paid accounts.": "Este enlace acepta por ahora mensajes de cuentas de pago.",
      "That eligibility check expired or was already used. Continue again to retry.": "Esa comprobación de acceso caducó o ya se usó. Continúa de nuevo para reintentar.",
      "Checking this contact link…": "Comprobando este enlace de contacto…",
      "Accepts": "Acepta",
      "Message size": "Tamaño del mensaje",
      "Up to {size} KB": "Hasta {size} KB",
      "Messages per day": "Mensajes por día",
      "Link expires": "El enlace caduca",
      "This link accepts messages only from identities its owner’s service considers eligible. The decision is made by that service, not by this page.": "Este enlace solo acepta mensajes de identidades que el servicio de su propietario considera con acceso. La decisión la toma ese servicio, no esta página.",
      "The recipient’s service accepted your message. This does not mean it has been read.": "El servicio del destinatario aceptó tu mensaje. Esto no significa que se haya leído.",
      "Sign in to send a message": "Inicia sesión para enviar un mensaje",
      "Messages through contact links always come from a verified identity, so the recipient knows who wrote them. Sign in, or create an account, and you will return to this link.": "Los mensajes por enlaces de contacto siempre provienen de una identidad verificada, para que el destinatario sepa quién los escribió. Inicia sesión o crea una cuenta y volverás a este enlace.",
      "Sign in to continue": "Inicia sesión para continuar",
      "Continuing reveals your handle and identity ({identity}) to {origin}. That site decides whether you are eligible.": "Si continúas, tu nombre de usuario e identidad ({identity}) se revelarán a {origin}. Ese sitio decide si tienes acceso.",
      "Nothing is shared until you continue. The check is valid for a few minutes and can be used once.": "No se comparte nada hasta que continúes. La comprobación es válida unos minutos y se puede usar una vez.",
      "Check again": "Comprobar de nuevo",
      "Continue as {identity}": "Continuar como {identity}",
      "Sending as {identity}": "Enviando como {identity}",
      "The recipient will see your identity. Only share information you intend them to keep.": "El destinatario verá tu identidad. Comparte solo información que quieras que conserve.",
      "This contact link sets what you can send and where it goes.": "Este enlace de contacto define qué puedes enviar y adónde va.",
      "Not used": "Sin usar",
      "Added automatically": "Se añade automáticamente",
      "Sender can choose": "Quien envía puede elegir",
      "Tags for this link": "Etiquetas de este enlace",
      "Automatic tags help you organize what arrives and are never shown to senders. Senders may pick from the optional tags, shown with the label you give them.": "Las etiquetas automáticas te ayudan a organizar lo que llega y nunca se muestran a quien envía. Quien envía puede elegir entre las etiquetas opcionales, mostradas con el nombre que les des.",
      "Use": "Uso",
      "Sender-facing label": "Nombre visible para quien envía",
      "Label senders see": "Nombre que ve quien envía",
      "Other automatic tags, separated by commas": "Otras etiquetas automáticas, separadas por comas",
      "Other optional tags, separated by commas": "Otras etiquetas opcionales, separadas por comas",
      "Use up to 32 tags in total. A tag is either automatic or optional.": "Usa hasta 32 etiquetas en total. Una etiqueta es automática u opcional.",
      "Edit this link’s tags.": "Edita las etiquetas de este enlace.",
      "Changes apply to future messages. The link and its limits stay the same, so you do not need to share it again.": "Los cambios se aplican a mensajes futuros. El enlace y sus límites no cambian, así que no necesitas compartirlo de nuevo.",
      "Save tags": "Guardar etiquetas",
      "Rotate this link’s challenge?": "¿Renovar el desafío de este enlace?",
      "A new link replaces the current one. Anyone holding the old link, and any eligibility checks already started, will need the new link. Limits, received messages and tags are kept.": "Un enlace nuevo reemplaza al actual. Quien tenga el enlace anterior, y cualquier comprobación de acceso ya iniciada, necesitará el nuevo. Se conservan los límites, los mensajes recibidos y las etiquetas.",
      "Rotate and show the new link": "Renovar y mostrar el nuevo enlace",
      "Name a tag.": "Pon nombre a una etiqueta.",
      "Label": "Nombre",
      "Renaming a label never changes which messages have the tag.": "Cambiar el nombre nunca cambia qué mensajes tienen la etiqueta.",
      "Save label": "Guardar nombre",
      "Allow conversation invitations (uses the older link format)": "Permitir invitaciones a conversaciones (usa el formato de enlace anterior)",
      "Anyone with this link can send within its limits, as a signed-in identity. Share it only with your intended recipients.": "Cualquiera con este enlace puede enviar dentro de sus límites, como identidad con sesión iniciada. Compártelo solo con quienes quieras.",
      "The developer contact link is unavailable right now.": "El enlace de contacto del desarrollador no está disponible ahora.",
      "Your account can currently message the developer. Eligibility is checked again when you send.": "Tu cuenta puede escribir al desarrollador por ahora. El acceso se comprueba de nuevo al enviar.",
      "Your account is not currently eligible to message the developer.": "Tu cuenta no tiene acceso por ahora para escribir al desarrollador.",
      "Your eligibility could not be checked right now. Try again shortly.": "No se pudo comprobar tu acceso en este momento. Inténtalo de nuevo en unos momentos.",
      "Developer contact is currently available to paid accounts.": "El contacto con el desarrollador está disponible por ahora para cuentas de pago.",
      "One contact link for everyone. Messages are accepted from paid accounts, and from every account while the service is in early access.": "Un enlace de contacto para todos. Se aceptan mensajes de cuentas de pago, y de todas las cuentas mientras el servicio esté en acceso anticipado.",
      "This link is valid until {date}.": "Este enlace es válido hasta {date}.",
      "Opening the link asks you to confirm your identity before you write. Tags identify your plan and topic; they do not guarantee a response time.": "Al abrir el enlace se te pedirá confirmar tu identidad antes de escribir. Las etiquetas identifican tu plan y tema; no garantizan un tiempo de respuesta.",
