      "Administrator · {handle}": "Administrador · {handle}",
      "Administrators cannot change their own account.": "Los administradores no pueden cambiar su propia cuenta.",
      "Administrators confirm with a passkey, and this account has none. Add a passkey under Account & security, then return.": "Los administradores confirman con una llave de acceso y esta cuenta no tiene ninguna. Añade una en Cuenta y seguridad y vuelve.",
      "Administrators confirm with a passkey. Add a passkey to this account under Account & security, then return.": "Los administradores confirman con una llave de acceso. Añade una a esta cuenta en Cuenta y seguridad y vuelve.",
      "Administrators create and edit user-class roles only.": "Los administradores solo crean y editan roles de clase usuario.",
      "Administrators mint only for runtime reservations.": "Los administradores solo emiten para reservas en tiempo de ejecución.",
      "After": "Después",
      "Aliases": "Alias",
      "All of its sessions end now and it cannot sign in until an administrator or boot reactivates it.": "Todas sus sesiones terminan ahora y no podrá iniciar sesión hasta que un administrador o boot la reactive.",
      "Assigned or retired handles are never released.": "Los identificadores asignados o retirados nunca se liberan.",
      "At a glance": "De un vistazo",
      "At {time}. After that, only a new boot token and redeploy can restore boot.": "El {time}. Después, solo un nuevo token de boot y un nuevo despliegue pueden restaurar boot.",
