      "Boot access countdown": "Cuenta atrás del acceso de boot",
      "Boot access ended early": "El acceso de boot terminó antes de tiempo",
      "Boot access ends at about {time} ({window} from now). Lost access needs a new token and redeploy.": "El acceso de boot termina hacia el {time} (dentro de {window}). Recuperar el acceso exige un nuevo token y un nuevo despliegue.",
      "Boot access ends in {time}": "El acceso de boot termina en {time}",
      "Boot access has ended": "El acceso de boot ha terminado",
      "Boot access has expired.": "El acceso de boot ha caducado.",
      "Boot already exists. Restoring replaces its credential and signs out every older boot session. Administrators, roles and claims stay as they are.": "Boot ya existe. Restaurarlo sustituye su credencial y cierra todas las sesiones de boot anteriores. Los administradores, roles y reclamaciones no cambian.",
      "Boot can act on this host until {time}.": "Boot puede actuar en este servidor hasta el {time}.",
      "Boot can mint for runtime and configured reservations.": "Boot puede emitir para reservas en tiempo de ejecución y configuradas.",
      "Boot can no longer sign in, step up or act. Administrators, roles and claims are unaffected. Claims boot minted stay usable until their own expiry.": "Boot ya no puede iniciar sesión, confirmar su identidad ni actuar. Los administradores, roles y reclamaciones no se ven afectados. Las reclamaciones emitidas por boot siguen siendo válidas hasta que caduquen.",
      "Boot console · Host administration": "Consola de boot · Administración del servidor",
      "Boot credential": "Credencial de boot",
      "Boot has not been claimed yet.": "Boot aún no se ha reclamado.",
      "Boot is claimed. This browser now holds a boot session.": "Boot está reclamado. Este navegador tiene ahora una sesión de boot.",
      "Boot is not configured": "Boot no está configurado",
      "Boot is restored. Older boot sessions no longer work.": "Boot está restaurado. Las sesiones de boot anteriores ya no funcionan.",
      "Boot is signed out everywhere and cannot sign in again. Only minting a new token and redeploying its digest restores boot. Administrators, roles and claims are unaffected.": "Boot cierra sesión en todas partes y no puede volver a iniciarla. Solo emitir un nuevo token y desplegar su resumen restaura boot. Los administradores, roles y reclamaciones no se ven afectados.",
      "Boot is this host’s deploy-token principal. It is not an account: it has no inbox, recovery file or directory entry, and its access ends after a fixed window.": "Boot es el principal de token de despliegue de este servidor. No es una cuenta: no tiene bandeja de entrada, archivo de recuperación ni entrada en el directorio, y su acceso termina tras un periodo fijo.",
      "Boot only": "Solo boot",
      "Boot password": "Contraseña de boot",
      "Boot setup is not configured on this deployment.": "La configuración de boot no está disponible en este despliegue.",
      "Boot signs in with the credential set when it was claimed or last restored. Boot sessions last at most one hour.": "Boot inicia sesión con la credencial definida al reclamarlo o restaurarlo por última vez. Las sesiones de boot duran como máximo una hora.",
      "Boot token": "Token de boot",
