      "Granted and revoked only by boot": "Solo boot lo concede y revoca",
      "Handles held back from public signup. Reserved handles become internal accounts only through a claim token.": "Identificadores apartados del registro público. Solo se convierten en cuentas internas mediante un token de reclamación.",
      "Hash-chained, append-only record of every privileged action.": "Registro encadenado por hash y de solo anexado de cada acción privilegiada.",
      "Hold": "Retención",
