      "Internal roles require a reserved internal account.": "Los roles internos requieren una cuenta interna reservada.",
      "It is removed from every role that lists it, and holders lose it immediately.": "Se quita de todos los roles que la incluyen y quienes la tienen la pierden de inmediato.",
