      "Privileged actions need a boot confirmation within the last few minutes. The action you started continues after you confirm.": "Las acciones privilegiadas necesitan una confirmación de boot de hace pocos minutos. La acción que iniciaste continúa después de confirmar.",
      "Privileged actions, including loading this console, need a passkey confirmation within the last few minutes. The action you started continues after you confirm.": "Las acciones privilegiadas, incluida la carga de esta consola, necesitan una confirmación con llave de acceso de hace pocos minutos. La acción que iniciaste continúa después de confirmar.",
      "Save class": "Guardar clase",
      "Copy it now.": "Cópialo ahora.",
      "This link is a bearer capability: anyone who opens it can claim this handle with the roles and badges listed here. Send it only to the intended person over a trusted channel. It is hidden when you leave this screen; only boot or the minting administrator can retrieve it again.": "Este enlace es una capacidad al portador: cualquiera que lo abra puede reclamar este identificador con los roles e insignias indicados aquí. Envíalo solo a la persona destinataria por un canal de confianza. Se oculta al salir de esta pantalla; solo boot o el administrador que lo emitió pueden recuperarlo.",
      "The server did not confirm the sign-out. This browser’s boot cookie was cleared; if this is a shared device, close the browser and sign in again later to verify.": "El servidor no confirmó el cierre de sesión. Se borró la cookie de boot de este navegador; si es un dispositivo compartido, cierra el navegador y vuelve a iniciar sesión más tarde para comprobarlo.",
      "Session ends in {time}. Sign in again soon.": "La sesión termina en {time}. Vuelve a iniciar sesión pronto."
